package local.tvmorph.tv;
public final class SeekHoldPolicyCheck {
 static void check(boolean ok,String name){if(!ok)throw new AssertionError(name);}
 public static void main(String[] args){SeekHoldPolicy p=new SeekHoldPolicy();check(p.begin(22,false,0,60000,7200000),"Start tap");check(p.position()==70000,"Tap previews exactly 10 seconds");p.advance(100);check(p.position()==70000,"No drift on short tap");p.reset();check(!p.begin(22,true,150,0,7200000),"Ignore stale repeat after release");p.begin(21,false,200,60000,7200000);check(p.position()==50000,"Left tap 10 seconds");p.reset();p.begin(22,false,0,60000,7200000);long previous=p.position(),early=0,late=0;int changes=0;for(int t=16;t<=4000;t+=16){if(t%400<16)p.begin(22,true,t,0,7200000);long next=p.advance(t),delta=next-previous;if(t<350)check(delta==0,"Wait before hold");else{check(delta>=0&&delta<2400,"Smooth bounded frame movement");if(delta>0)changes++;if(t==400)early=delta;if(t==3600)late=delta;}previous=next;}check(changes>200,"Continuous frame updates independent of key-repeat frequency");check(late>early,"Progressive acceleration");long stop=p.position();p.reset();check(p.advance(9000)==stop,"No movement after cancellation");p.begin(21,false,10000,3000,120000);check(p.position()==0,"Clamp start");p.reset();p.begin(22,false,11000,119000,120000);check(p.position()==119000,"Clamp end");check(p.stale(12201),"Missing-keyup watchdog");System.out.println("PASS native scrub: exact 10-second taps, smooth frame preview, gradual acceleration, boundaries, cancellation and stale-key protection.");}
}
